<script setup lang="ts">
import { onMounted, onUnmounted } from 'vue'
import { api, hasRole } from '../api'
import { useLoad, time } from '../composables'
import type { Overview, Page, Incident } from '../types'
import StatusBadge from '../components/StatusBadge.vue'
import PageState from '../components/PageState.vue'
import AppIcon from '../components/AppIcon.vue'
const {data,loading,error,load}=useLoad(async()=>({summary:await api<Overview>('/overview'),incidents:await api<Page<Incident>>('/incidents?size=5')}))
onMounted(load);const interval=setInterval(load,30000);onUnmounted(()=>clearInterval(interval))
</script>
<template><div class="page-heading"><div><h1>运行概览</h1><p>关注服务变化，让需要处理的事故保持可见。</p></div><button class="btn" :disabled="loading" @click="load"><AppIcon name="refresh" :size="16" />刷新</button></div>
<PageState :loading="loading&&!data" :error="error" @retry="load"><template v-if="data"><div class="summary-strip"><div><span>服务目标</span><strong>{{ data.summary.totalTargets }}</strong><small>{{ data.summary.activeChecks }} 项检查正在监控</small></div><div><span><i class="dot good"></i>运行正常</span><strong>{{ data.summary.up }}</strong><small>检查结果在有效时间内</small></div><div><span><i class="dot danger"></i>服务异常</span><strong>{{ data.summary.down }}</strong><small>最近检查返回异常</small></div><div><span><i class="dot warning"></i>活动事故</span><strong>{{ data.summary.activeIncidents }}</strong><small>{{ data.summary.unknown }} 个目标状态未知</small></div></div>
<div class="overview-columns"><section class="panel"><div class="panel-heading"><h2>服务状态</h2><RouterLink to="/targets" class="text-link">全部目标 <AppIcon name="chevron" :size="14" /></RouterLink></div><PageState :empty="data.summary.targets.length===0" title="从第一个服务开始" description="登记一个健康检查地址，启用检查后在这里查看状态。"><template #action><RouterLink v-if="hasRole('OPS_ADMIN')" to="/targets/new" class="btn primary">登记服务目标</RouterLink><p v-else class="muted">请管理员为你分配目标读取权限。</p></template><div class="table-scroll"><table><thead><tr><th>服务目标</th><th>环境</th><th>当前状态</th><th>最近检查</th></tr></thead><tbody><tr v-for="t in data.summary.targets" :key="t.id"><td><RouterLink :to="'/targets/'+t.id" class="row-title">{{ t.name }}</RouterLink><small class="cell-note mono">{{ t.code }}</small></td><td><span class="env-tag">{{ t.environment }}</span></td><td><StatusBadge :value="t.health" /></td><td class="timestamp">{{ time(t.lastCheckedAt) }}</td></tr></tbody></table></div></PageState><div class="panel-footnote">无检查、已暂停或证据过期时，状态显示为未知。最多展示 20 个目标。</div></section>
<section class="panel"><div class="panel-heading"><h2>最近事故</h2><RouterLink to="/incidents" class="text-link">事故队列 <AppIcon name="chevron" :size="14" /></RouterLink></div><PageState :empty="!data.incidents.items.length" title="尚无事故记录" description="连续失败达到阈值后，系统会自动创建事故。"><div class="incident-preview-list"><RouterLink v-for="i in data.incidents.items" :key="i.id" :to="'/incidents/'+i.id" class="incident-preview"><div><span class="severity">{{ i.severity }}</span><StatusBadge :value="i.status" /></div><strong>{{ i.targetName }}</strong><p>{{ i.summary }}</p><small>{{ time(i.openedAt) }}</small></RouterLink></div></PageState></section></div><div class="data-caption">数据更新于 {{ time(data.summary.generatedAt) }} · 每 30 秒刷新</div></template></PageState></template>
